// Formate une soumission Netlify `devis-intelligent` en message Telegram
// et en e-mail HTML lisibles. Aucun champ vide n'est affiché.

const body = $input.first().json.body ?? $input.first().json;
const d = body.data ?? {};

if (body.form_name && body.form_name !== 'devis-intelligent' && body.form_name !== 'devis-transport') {
  return [];
}

const t = (v) => (v === undefined || v === null ? '' : String(v).trim());
const has = (v) => t(v).length > 0;

// Libellés lisibles pour les valeurs codées du wizard
const L = {
  local: 'local', 'longue-distance': 'longue distance', international: 'international',
  studio: 'studio', t1: 'T1', t2: 'T2', t3: 'T3', t4: 'T4', 't5-plus': 'T5 et plus',
  maison: 'maison', bureau: 'bureau', garde_meuble: 'garde-meuble',
  oui: 'oui', non: 'non', 'peut-etre': 'peut-être',
  'oui-grand': 'grand ascenseur', 'oui-petit': 'petit ascenseur', 'non-ascenseur': 'sans ascenseur',
  'devant-porte': 'devant la porte', 'moins-30m': '< 30 m', 'plus-30m': '> 30 m',
  'rue-etroite': 'rue étroite', 'zone-pietonne': 'zone piétonne', 'cour-interieure': 'cour intérieure',
  'plus-moins-1-semaine': '± 1 semaine', 'plus-moins-3-jours': '± 3 jours',
  'date-ferme': 'date ferme', flexible: 'flexible',
  telephone: 'téléphone', sms: 'SMS', whatsapp: 'WhatsApp', email: 'e-mail',
  'des-que-possible': 'dès que possible',
};
const lab = (v) => L[t(v)] ?? t(v);

const dateFr = (iso) => {
  if (!has(iso)) return '';
  const parts = t(iso).split('-');
  if (parts.length !== 3) return t(iso);
  const mois = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
  return `${Number(parts[2])} ${mois[Number(parts[1]) - 1]} ${parts[0]}`;
};

const etage = (v) => {
  const n = t(v);
  if (!has(n)) return '';
  if (n === '0') return 'RDC';
  if (n === '1') return '1er étage';
  return `${n}e étage`;
};

// ---------- Construction des blocs ----------
const lignes = [];
const push = (s) => lignes.push(s);

const nom = has(d.nom) ? d.nom : 'Sans nom';
push(`🚚 <b>NOUVELLE DEMANDE</b>`);
push('');
push(`👤 <b>${nom}</b>`);
if (has(d.telephone)) push(`   📞 ${d.telephone}`);
if (has(d.email)) push(`   ✉️ ${d.email}`);
const contact = [has(d.contact_prefere) ? lab(d.contact_prefere) : '', has(d.creneau_rappel) ? `rappel ${lab(d.creneau_rappel)}` : ''].filter(Boolean).join(' · ');
if (contact) push(`   ${contact}`);

push('');
push(`📍 <b>TRAJET</b>${has(d.type_trajet) ? ` · ${lab(d.type_trajet)}` : ''}`);
const dep = [t(d.depart_ville), has(d.depart_code_postal) ? `(${d.depart_code_postal})` : ''].filter(Boolean).join(' ');
const arr = [t(d.arrivee_ville), has(d.arrivee_code_postal_pays) ? `(${d.arrivee_code_postal_pays})` : ''].filter(Boolean).join(' ');
if (dep || arr) push(`   ${dep || '?'} → ${arr || '?'}`);
const quand = [dateFr(d.date_souhaitee), has(d.flexibilite_date) ? lab(d.flexibilite_date) : ''].filter(Boolean).join(' · ');
if (quand) push(`   ${quand}`);

const bloc = (titre, logement, surface, et, asc, stat, acces) => {
  const items = [];
  const tete = [has(logement) ? lab(logement) : '', has(surface) ? `${surface} m²` : ''].filter(Boolean).join(' · ');
  const niveau = [etage(et), has(asc) ? lab(asc) : ''].filter(Boolean).join(' · ');
  const bas = [has(stat) ? `stationnement ${lab(stat)}` : '', has(acces) ? lab(acces) : ''].filter(Boolean).join(' · ');
  if (tete) items.push(`   ${tete}`);
  if (niveau) items.push(`   ${niveau}${t(asc) === 'non-ascenseur' && t(et) !== '0' ? '  ⚠️' : ''}`);
  if (bas) items.push(`   ${bas}`);
  if (items.length) { push(''); push(`${titre}`); items.forEach(push); }
};
bloc('🏠 <b>DÉPART</b>', d.logement_depart, d.surface_depart_m2, d.etage_depart, d.ascenseur_depart, d.stationnement_depart, d.acces_depart);
bloc('🏢 <b>ARRIVÉE</b>', d.logement_arrivee, '', d.etage_arrivee, d.ascenseur_arrivee, d.stationnement_arrivee, '');

const vol = [];
if (has(d.volume_m3)) vol.push(`${d.volume_m3} m³`);
if (has(d.nombre_cartons)) vol.push(`${d.nombre_cartons} cartons`);
if (has(d.nombre_meubles_volumineux)) vol.push(`${d.nombre_meubles_volumineux} meubles volumineux`);
if (has(d.nombre_electromenager)) vol.push(`${d.nombre_electromenager} électroménager`);
const alertes = [];
if (t(d.objet_piano) === 'oui') alertes.push('piano');
if (t(d.objet_lourd) === 'oui') alertes.push('objet lourd');
if (t(d.objet_fragile) === 'oui') alertes.push('objets fragiles');
if (t(d.objet_tres_grand) === 'oui') alertes.push('objet très grand');
if (vol.length || alertes.length) {
  push(''); push('📦 <b>VOLUME</b>');
  if (vol.length) push(`   ${vol.join(' · ')}`);
  if (alertes.length) push(`   ⚠️ ${alertes.join(' · ')}`);
}

const serv = [];
if (t(d.service_cartons) === 'oui') serv.push('fourniture de cartons');
if (t(d.service_emballage) === 'oui') serv.push('emballage');
if (t(d.service_demontage) === 'oui') serv.push('démontage');
if (t(d.service_deballage) === 'oui') serv.push('déballage');
if (serv.length) { push(''); push('✅ <b>SERVICES</b>'); push(`   ${serv.join(' · ')}`); }

if (has(d.inventaire_details)) {
  push(''); push('📝 <b>PRÉCISIONS</b>');
  push(`   ${t(d.inventaire_details).slice(0, 500)}`);
}

if (has(d.visite_video) && t(d.visite_video) !== 'non') {
  push(''); push(`📹 Visite vidéo : ${lab(d.visite_video)}${has(d.creneau_visite_video) ? ` · ${d.creneau_visite_video}` : ''}`);
}

if (has(d.estimation_min) && has(d.estimation_max)) {
  push(''); push(`💶 <b>Estimation indicative : ${d.estimation_min} – ${d.estimation_max} €</b>`);
  push(`   <i>non contractuelle</i>`);
}

const src = [has(d.lead_source) ? d.lead_source : '', has(d.landing_page) ? d.landing_page : ''].filter(Boolean).join(' · ');
const utm = ['utm_source','utm_medium','utm_campaign','utm_content'].map(k => has(d[k]) ? `${k.replace('utm_','')}=${d[k]}` : '').filter(Boolean).join(' · ');
push('');
if (src) push(`🔗 ${src}`);
if (utm) push(`   ${utm}`);

const telegram = lignes.join('\n');

// ---------- E-mail HTML ----------
const esc = (s) => t(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rows = [];
const row = (k, v) => { if (has(v)) rows.push(`<tr><th align="left" style="padding:7px 14px 7px 0;color:#6b7280;font-weight:600;white-space:nowrap;vertical-align:top">${esc(k)}</th><td style="padding:7px 0;color:#15191c">${esc(v)}</td></tr>`); };
const section = (titre) => rows.push(`<tr><td colspan="2" style="padding:20px 0 6px;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#a8703f;font-weight:700;border-bottom:1px solid #e5e1d8">${esc(titre)}</td></tr>`);

section('Contact');
row('Nom', d.nom); row('Téléphone', d.telephone); row('E-mail', d.email);
row('Contact préféré', lab(d.contact_prefere)); row('Créneau de rappel', lab(d.creneau_rappel));
section('Trajet');
row('Type', lab(d.type_trajet)); row('Départ', dep); row('Arrivée', arr);
row('Date souhaitée', dateFr(d.date_souhaitee)); row('Flexibilité', lab(d.flexibilite_date));
section('Départ');
row('Logement', lab(d.logement_depart)); row('Surface', has(d.surface_depart_m2) ? `${d.surface_depart_m2} m²` : '');
row('Étage', etage(d.etage_depart)); row('Ascenseur', lab(d.ascenseur_depart));
row('Stationnement', lab(d.stationnement_depart)); row('Accès', lab(d.acces_depart));
section('Arrivée');
row('Logement', lab(d.logement_arrivee)); row('Étage', etage(d.etage_arrivee));
row('Ascenseur', lab(d.ascenseur_arrivee)); row('Stationnement', lab(d.stationnement_arrivee));
section('Volume et objets');
row('Volume', has(d.volume_m3) ? `${d.volume_m3} m³` : ''); row('Cartons', d.nombre_cartons);
row('Meubles volumineux', d.nombre_meubles_volumineux); row('Électroménager', d.nombre_electromenager);
row('Objets signalés', alertes.join(', ')); row('Précisions', d.inventaire_details);
section('Services et suite');
row('Services demandés', serv.join(', ')); row('Visite vidéo', lab(d.visite_video));
row('Créneau visite', d.creneau_visite_video);
row('Estimation', has(d.estimation_min) ? `${d.estimation_min} – ${d.estimation_max} € (non contractuelle)` : '');
section('Origine');
row('Source', d.lead_source); row('Page', d.landing_page); row('Referrer', d.referrer);
['utm_source','utm_medium','utm_campaign','utm_term','utm_content'].forEach(k => row(k, d[k]));
row('Version du formulaire', d.form_version);

const html = `<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:640px;margin:0 auto;padding:24px;background:#fafaf7">
<h1 style="margin:0 0 4px;font-size:20px;color:#15191c">Nouvelle demande de devis</h1>
<p style="margin:0 0 18px;color:#6b7280;font-size:14px">${esc(nom)}${has(d.telephone) ? ` · <a href="tel:${esc(d.telephone)}" style="color:#a8703f">${esc(d.telephone)}</a>` : ''}</p>
<table cellpadding="0" cellspacing="0" style="width:100%;font-size:14px;line-height:1.5">${rows.join('')}</table>
<p style="margin:22px 0 0;color:#9ca3ac;font-size:12px">Envoyé automatiquement depuis transportcarcassonne.fr. L'estimation est indicative et ne vaut pas devis.</p>
</div>`;

const sujet = `Devis ${has(d.depart_ville) ? d.depart_ville : '?'} → ${has(d.arrivee_ville) ? d.arrivee_ville : '?'} · ${nom}`;

return [{ json: { telegram, html, sujet } }];
